case = int(input())
for _ in range(case):
	(n, m, q) = map(int, input().split(' '))
	rows = {}
	col = {}
	for i in range(q):
		(x, y) = map(int, input().split(' '))
		if x not in rows:
			rows[x] = 0
		if y not in col:
			col[y] = 0
		rows[x] += 1
		col[y] += 1
	rowodds = 0
	for key in rows:
		if rows[key] & 1 == 1:
			rowodds += 1
	colodds = 0
	for key in col:
		if col[key] & 1 == 1:
			colodds += 1
	res = rowodds * m + colodds * n - rowodds * colodds * 2
	print(res)
